        "type": "string",
        "description": "提醒用户尽快打车的补充说明",
        "sampleValue": "出门快不行了"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转打车软件的动作文案",
        "sampleValue": "去打车"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_weathe2.png",
      "description": "天气/雨伞图标，适合雨天出行提醒中作为主状态识别图标。",
      "bindTo": "/asset/primaryIcon"
    },
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车图标，适合雨天打车入口或叫车动作提示。",
      "bindTo": "/asset/actionIcon"
    }
  ]
}

